<script setup lang="ts">
import type {BsPublicBookingForm,BsPublicBookingView} from '../types/appointmentBookingPresentation'
defineProps<{view:BsPublicBookingView}>()
const form=defineModel<BsPublicBookingForm>('form',{required:true}),verifyOpen=defineModel<boolean>('verifyOpen',{default:false}),cancelOpen=defineModel<boolean>('cancelOpen',{default:false})
const emit=defineEmits<{verify:[];logout:[];retry:[];slots:[];create:[];reschedule:[reference:string];saveReschedule:[];requestCancel:[reference:string];cancel:[];mode:[value:'create'|'manage'];page:[page:number]}>()
function update(key:keyof BsPublicBookingForm,value:string|number|null){form.value={...form.value,[key]:String(value??''),...(key==='selection'||key==='date'?{startsAt:''}:{})}}
</script>
<template>
 <div class="bs-public-booking" :lang="view.locale" :dir="view.locale==='ar'?'rtl':'ltr'">
  <header class="bs-public-booking__header"><a :href="view.homeHref" class="bs-public-booking__brand"><img :src="view.logo" :alt="view.shopName" width="48" height="48"><strong>{{view.shopName}}</strong></a><nav :aria-label="view.copy.language"><a v-for="link in view.languages" :key="link.locale" :href="link.href" :lang="link.locale" :aria-current="link.locale===view.locale?'page':undefined">{{link.label}}</a></nav></header>
  <main class="bs-public-booking__main"><BsHeading :level="1">{{view.copy.title}}</BsHeading>
   <BsAlert v-if="view.error" tone="error">{{view.error}}</BsAlert><BsText v-if="view.success" role="status">{{view.success}}</BsText>
   <BsText v-if="view.loading" role="status">{{view.copy.loading}}</BsText>
   <BsPanel v-else-if="!view.enabled" padding="lg"><BsText as="p">{{view.copy.unavailable}}</BsText><BsButton :disabled="view.pending" @click="emit('retry')">{{view.copy.retry}}</BsButton></BsPanel>
   <template v-else>
    <BsText as="p">{{view.copy[view.scope]}}</BsText><BsText as="p" tone="muted">{{view.rules}}</BsText><BsText as="p" size="sm" tone="muted">{{view.copy.remindersDisabled}}</BsText>
    <BsPanel v-if="view.accessCode" padding="lg"><BsStack gap="md"><BsHeading :level="2">{{view.copy.saveCode}}</BsHeading><output class="bs-public-booking__code" dir="ltr">{{view.accessCode}}</output><BsText as="p">{{view.copy.codeHelp}}</BsText></BsStack></BsPanel>
    <BsInline wrap><BsButton v-if="view.canCreate" :disabled="view.pending" :aria-pressed="view.mode==='create'" @click="emit('mode','create')">{{view.copy.newBooking}}</BsButton><BsButton v-if="view.authenticated" :disabled="view.pending" :aria-pressed="view.mode==='manage'" @click="emit('mode','manage')">{{view.copy.manage}}</BsButton><BsButton v-if="!view.authenticated" :disabled="view.pending" @click="verifyOpen=true">{{view.copy.verify}}</BsButton><BsButton v-else :disabled="view.pending" @click="emit('logout')">{{view.copy.logout}}</BsButton></BsInline>
    <BsPanel v-if="view.mode==='create'&&view.canCreate||view.mode==='reschedule'" padding="lg"><BsStack gap="md">
     <BsHeading :level="2">{{view.mode==='reschedule'?view.copy.reschedule:view.copy.newBooking}}</BsHeading>
     <BsField v-slot="field" :label="view.copy.selection"><BsSelect :virtual="true" :virtual-scroller-options="{itemSize:44}" :filter="true" :input-id="field.id" :label="view.copy.selection" :model-value="form.selection" :options="view.selectionOptions" option-label="label" option-value="value" :disabled="view.pending||view.mode==='reschedule'" @update:model-value="update('selection',$event)"/></BsField>
     <BsDescriptionList v-if="view.selectionDetails.length"><BsDescriptionItem v-for="detail in view.selectionDetails" :key="detail.term" :term="detail.term">{{detail.value}}</BsDescriptionItem></BsDescriptionList>
     <BsField v-slot="field" :label="view.copy.date"><BsInput :id="field.id" type="date" :model-value="form.date" :min="view.dateMin" :max="view.dateMax" required :disabled="view.pending" @update:model-value="update('date',$event)"/></BsField>
     <BsButton :disabled="view.pending||!form.selection||!form.date" @click="emit('slots')">{{view.copy.loadSlots}}</BsButton>
     <BsText v-if="!view.slotOptions.length" role="status">{{view.copy.noSlots}}</BsText>
     <BsForm :pending="view.pending" @submit="view.mode==='reschedule'?emit('saveReschedule'):emit('create')">
      <BsField v-slot="field" :label="view.copy.slot" required><BsSelect :virtual="true" :virtual-scroller-options="{itemSize:44}" :input-id="field.id" :label="view.copy.slot" :model-value="form.startsAt" :options="view.slotOptions" option-label="label" option-value="value" :disabled="view.pending" @update:model-value="update('startsAt',$event)"/></BsField>
      <template v-if="view.scope==='guest'&&view.mode==='create'"><BsField v-slot="field" :label="view.copy.name" required><BsInput :id="field.id" :model-value="form.name" autocomplete="off" :minlength="2" :maxlength="160" required @update:model-value="update('name',$event)"/></BsField><BsField v-slot="field" :label="view.copy.phone" required><BsInput :id="field.id" type="tel" :model-value="form.phone" autocomplete="off" dir="ltr" :maxlength="40" required @update:model-value="update('phone',$event)"/></BsField></template>
      <BsInline wrap><BsButton variant="primary" type="submit" :pending="view.pending" :disabled="!form.startsAt">{{view.mode==='reschedule'?view.copy.reschedule:view.copy.create}}</BsButton><BsButton v-if="view.mode==='reschedule'" :disabled="view.pending" @click="emit('mode','manage')">{{view.copy.back}}</BsButton></BsInline>
     </BsForm>
    </BsStack></BsPanel>
    <template v-if="view.mode==='manage'"><BsText v-if="!view.rows.length" role="status">{{view.copy.noManage}}</BsText><ol class="bs-public-booking__list"><li v-for="row in view.rows" :key="row.reference"><BsStack gap="sm"><BsText emphasis="semibold">{{row.date}}</BsText><BsHeading :level="2">{{row.service}}</BsHeading><BsText>{{row.staff}}</BsText><BsText>{{row.location}}</BsText><BsInline wrap><BsButton v-if="row.canReschedule" :disabled="view.pending" @click="emit('reschedule',row.reference)">{{view.copy.reschedule}}</BsButton><BsButton v-if="row.canCancel" :disabled="view.pending" @click="emit('requestCancel',row.reference)">{{view.copy.cancel}}</BsButton></BsInline></BsStack></li></ol><BsPagination :page="view.managePage" :total="view.manageTotal" :page-size="20" :label="view.copy.manage" :previous-label="view.copy.previous" :next-label="view.copy.next" @update:page="emit('page',$event)"/></template>
   </template>
   <BsInline wrap><a :href="view.homeHref">{{view.copy.home}}</a><a :href="view.portalHref">{{view.copy.portal}}</a></BsInline>
  </main>
  <BsRecordActionDialog v-model:visible="verifyOpen" :title="view.copy.verify" :dirty="false" :pending="view.pending" :error="view.error" :submit-label="view.copy.verify" :cancel-label="view.copy.back" @submit="emit('verify')"><BsText as="p">{{view.copy.verifyHelp}}</BsText><BsField v-slot="field" :label="view.copy.code" required><BsInput :id="field.id" :model-value="form.code" autocomplete="off" dir="ltr" :maxlength="32" required @update:model-value="update('code',$event)"/></BsField><BsField v-slot="field" :label="view.copy.phone" required><BsInput :id="field.id" type="tel" :model-value="form.verifyPhone" autocomplete="off" dir="ltr" :maxlength="40" required @update:model-value="update('verifyPhone',$event)"/></BsField></BsRecordActionDialog>
  <BsRecordActionDialog v-model:visible="cancelOpen" :title="view.copy.confirmCancel" :dirty="false" :pending="view.pending" :error="view.error" :submit-label="view.copy.cancel" :cancel-label="view.copy.back" @submit="emit('cancel')"><BsText as="p">{{view.cancelSummary}}</BsText><BsText as="p">{{view.copy.cancelHelp}}</BsText></BsRecordActionDialog>
 </div>
</template>
<style scoped>
.bs-public-booking{min-height:100vh;background:var(--bs-bg);color:var(--bs-text);}.bs-public-booking a{color:var(--bs-text);text-underline-offset:.25em;overflow-wrap:anywhere;}.bs-public-booking a:focus-visible{outline:3px solid var(--bs-focus-ring,var(--bs-primary));outline-offset:4px;}
.bs-public-booking__header,.bs-public-booking__main{max-width:66rem;margin-inline:auto;padding-inline:clamp(1rem,4vw,3rem);}.bs-public-booking__header{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-block:1.25rem;border-bottom:1px solid var(--bs-border);}.bs-public-booking__brand{display:flex;align-items:center;gap:.75rem;text-decoration:none;min-width:0;}.bs-public-booking__brand img{object-fit:contain;flex-shrink:0;}.bs-public-booking__header nav{display:flex;gap:1rem;flex-shrink:0;}.bs-public-booking__main{display:grid;gap:1.5rem;padding-block:clamp(2rem,5vw,4rem);}.bs-public-booking__code{font-size:var(--bs-font-size-2xl,1.5rem);font-weight:700;letter-spacing:.1em;overflow-wrap:anywhere;}.bs-public-booking__list{list-style:none;margin:0;padding:0;}.bs-public-booking__list li{padding-block:1.5rem;border-bottom:1px solid var(--bs-border);overflow-wrap:anywhere;}@media(max-width:42rem){.bs-public-booking__header{align-items:start;}.bs-public-booking__brand img{width:36px;height:36px;}}
</style>
